import{_ as s,o as n,c as e,a0 as t}from"./chunks/framework.CNDWyMYS.js";const h=JSON.parse('{"title":"Creating LuaRocks with GNU autotools","description":"","frontmatter":{},"headers":[],"relativePath":"creating_luarocks_with_gnu_autotools.md","filePath":"creating_luarocks_with_gnu_autotools.md"}'),p={name:"creating_luarocks_with_gnu_autotools.md"};function o(l,a,i,c,r,u){return n(),e("div",null,[...a[0]||(a[0]=[t(`<h1 id="creating-luarocks-with-gnu-autotools" tabindex="-1">Creating LuaRocks with GNU autotools <a class="header-anchor" href="#creating-luarocks-with-gnu-autotools" aria-label="Permalink to &quot;Creating LuaRocks with GNU autotools&quot;">​</a></h1><p>Note that LuaRocks requires packages to be relocatable, and GNU autotools by default builds non-relocatable packages. For many programs it&#39;s not necessary to do anything particular to make them relocatable; applications which need to find resources at run-time may be problematic. See GNU Smalltalk for one approach (look at the RELOCATABILITY section in its configure.ac). <a href="https://github.com/rrthomas/zee" target="_blank" rel="noreferrer">Zee</a> uses another approach, of patching in paths for in-place running of the program during development, and relying on Lua search paths at run-time, purely to find Lua modules. Search for &#39;in_place_lua_path&#39;.</p><p>Use a rockspec template like the following, and call it $PACKAGE.rockspec.in:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>package=&quot;@PACKAGE@&quot;</span></span>
<span class="line"><span> version=&quot;@VERSION@-1&quot;</span></span>
<span class="line"><span> source = {</span></span>
<span class="line"><span>   url = &quot;https://github.com/downloads/&lt;USER&gt;/@PACKAGE@/@PACKAGE@-@VERSION@.tar.gz&quot;,</span></span>
<span class="line"><span>   md5 = &quot;@MD5@&quot;,</span></span>
<span class="line"><span>   dir = &quot;@PACKAGE@-@VERSION@&quot;</span></span>
<span class="line"><span> }</span></span>
<span class="line"><span> description = {</span></span>
<span class="line"><span>   summary = &quot;&lt;Short summary&gt;&quot;,</span></span>
<span class="line"><span>   detailed = [[</span></span>
<span class="line"><span>       &lt;Detailed information.&gt;</span></span>
<span class="line"><span>   ]],</span></span>
<span class="line"><span>   homepage = &quot;https://github.com/&lt;USER&gt;/@PACKAGE@&quot;,</span></span>
<span class="line"><span>   license = &quot;&lt;LICENSE&gt;&quot;</span></span>
<span class="line"><span> }</span></span>
<span class="line"><span> dependencies = {</span></span>
<span class="line"><span>   &quot;lua &gt;= 5.1&quot;</span></span>
<span class="line"><span> }</span></span>
<span class="line"><span> build = {</span></span>
<span class="line"><span>   type = &quot;command&quot;,</span></span>
<span class="line"><span>   build_command = &quot;LUA=$(LUA) CPPFLAGS=-I$(LUA_INCDIR) ./configure --prefix=$(PREFIX) --libdir=$(LIBDIR) --datadir=$(LUADIR) &amp;&amp; make clean &amp;&amp; make&quot;,</span></span>
<span class="line"><span>   install_command = &quot;make install&quot;</span></span>
<span class="line"><span> }</span></span></code></pre></div><p>Add &quot;$PACKAGE.rockspec.in&quot; to AC_CONFIG_FILES in your configure.ac:</p><p>Add or amend the following rules in your Makefile.am:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ROCKSPEC = $(PACKAGE)-$(VERSION)-1.rockspec</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$(ROCKSPEC): $(PACKAGE).rockspec dist</span></span>
<span class="line"><span> 	sed -e &#39;s/@MD5@/&#39;\`$(MD5SUM) $(distdir).tar.gz | \\</span></span>
<span class="line"><span> 	cut -d &quot; &quot; -f 1\`&#39;/g&#39; &lt; $(PACKAGE).rockspec &gt; $@</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>EXTRA_DIST = $(PACKAGE).rockspec.in</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>DISTCLEANFILES = $(PACKAGE).rockspec</span></span></code></pre></div><p>You can use <a href="https://github.com/rrthomas/woger" target="_blank" rel="noreferrer">woger</a> to automate your releases, uploading rockspecs to luarocks.org and announcements to the Lua mailing list. The details are evolving, so see woger itself for details, and a frequently-updated project such as <a href="https://github.com/luaposix/luaposix" target="_blank" rel="noreferrer">luaposix</a> for example Makefile.am code.</p>`,11)])])}const g=s(p,[["render",o]]);export{h as __pageData,g as default};
